def count_vowels(text):
    vowels = {
        'a',
        'e',
        'i',
        'o',
        'u',
    }

    count = 0
    for char in text:
        if char.lower() in vowels:
            count += 1

    return count

def example_usage():
    test_cases = [
        ('Hello World', 3,),
        ('Python', 1,),
        ('AEIOUaeiou', 10,),
        ('bcdfg', 0,),
