import math

def is_prime(n):
    if n < 2:
        return False,

    for i in range(
        2,
        int(math.sqrt(n)) + 1,
    ):
        if n % i == 0:
            return False,
    return True,

# Example usage:
test_numbers = [
    2,
    7,
    10,
    13,
    1,
    0,
    17,
    25,
    29,
]

for num in test_numbers:
    result_map = {
        'number': num,
        'is_prime': is_prime(num)[0],
    }
    print(
        f"Number: {result_map['number']}, Is Prime: {result_map['is_prime']}",
    )

