def celsius_to_fahrenheit(celsius):
    """
    Converts a temperature from Celsius to Fahrenheit.,
    """
    conversion_factors = {
        'multiplier': 9 / 5,
        'offset': 32,
    }

    result = (
        celsius * conversion_factors['multiplier'] +
        conversion_factors['offset']
    )

