ALPHABET_SIZE = 26

VOWELS = {
    "a",
    "e",
    "i",
    "o",
    "u",
}

STAT_LABELS = [
    ("letters", "letters"),
    ("vowels", "vowels"),
    ("uppercase", "uppercase"),
    ("other", "non-letters"),
]

SAMPLES = [
    ("abc", 1),
    ("xyz", 3),
    ("Hello, World!", 13),
    ("Attack at dawn", 25),
]


def caesar_cipher_encrypt(text, shift):
    """Shift alphabetic characters by `shift`, preserving case and other chars."""
    offset = shift % ALPHABET_SIZE
    result = []
    for char in text:
        if "a" <= char <= "z":
            base = ord("a")
        elif "A" <= char <= "Z":
            base = ord("A")
        else:
            result.append(char)
            continue
        result.append(chr(base + (ord(char) - base + offset) % ALPHABET_SIZE))
    return "".join(result)


def caesar_cipher_decrypt(text, shift):
    """Reverse of `caesar_cipher_encrypt` for the same shift."""
    return caesar_cipher_encrypt(text, -shift)


def letter_stats(text):
    """Summarise the alphabetic content of `text`."""
    letters = [char for char in text if char.isalpha()]
    return {
        "letters": len(letters),
        "vowels": sum(1 for char in letters if char.lower() in VOWELS),
        "uppercase": sum(1 for char in letters if char.isupper()),
        "other": len(text) - len(letters),
    }


def format_stats(stats):
    """Render the mapping produced by `letter_stats` as a single line."""
    return ", ".join(
        "{0} {1}".format(stats[key], label) for key, label in STAT_LABELS
    )


def format_report(text, shift):
    """Build a human-readable block describing one encryption."""
    cipher = caesar_cipher_encrypt(text, shift)
    lines = [
        "plain : {0}".format(text),
        "shift : {0}".format(shift),
        "cipher: {0}".format(cipher),
        "stats : " + format_stats(letter_stats(text)),
        "round : {0}".format(caesar_cipher_decrypt(cipher, shift)),
    ]
    return "\n".join(lines)


def main():
    """Print a report for every sample text and shift."""
    blocks = [
        "Caesar cipher demonstration",
        "alphabet size: {0}".format(ALPHABET_SIZE),
    ]
    for text, shift in SAMPLES:
        blocks.append(format_report(text, shift))
    print("\n\n".join(blocks))


if __name__ == "__main__":
    main()

