"""Squares of the integers from 1 to n, plus a small table report."""

REPORT_COLUMNS = [
    "n",
    "count",
    "squares",
    "total",
]

COLUMN_WIDTHS = {
    "n": 4,
    "count": 6,
    "squares": 32,
    "total": 8,
}


def validate_count(n):
    """Return n as a plain non-negative int, rejecting anything else."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError(
            "n must be an int, got {}".format(type(n).__name__),
        )
    if n < 0:
        raise ValueError(
            "n must be non-negative, got {}".format(n),
        )
    return n


def list_of_squares(n):
    """Return [1**2, 2**2, ..., n**2]; an empty list when n is 0."""
    limit = validate_count(n)
    return [i * i for i in range(1, limit + 1)]


def sum_of_squares(n):
    """Return the sum of the first n squares."""
    return sum(list_of_squares(n))


def format_squares(squares):
    """Render a square list, truncating it to fit the report column."""
    text = "[" + ", ".join(str(value) for value in squares) + "]"
    width = COLUMN_WIDTHS["squares"]
    if len(text) > width:
        text = text[: width - 4].rstrip(", ") + ", ...]"
    return text


def render_row(cells):
    """Pad cells to the report column widths and join them."""
    padded = [
        str(cell).ljust(COLUMN_WIDTHS[name])
        for name, cell in zip(REPORT_COLUMNS, cells)
    ]
    return ("| " + " | ".join(padded)).rstrip()


def build_report(counts):
    """Build the report lines for every n in counts."""
    lines = [
        render_row(REPORT_COLUMNS),
        "-" * (sum(COLUMN_WIDTHS.values()) + 3 * len(REPORT_COLUMNS)),
    ]
    grand_total = 0
    for n in counts:
        squares = list_of_squares(n)
        total = sum_of_squares(n)
        grand_total += total
        cells = [
            n,
            len(squares),
            format_squares(squares),
            total,
        ]
        lines.append(render_row(cells))
    summary = [
        "rows: {}".format(len(counts)),
        "largest n: {}".format(max(counts, default=0)),
        "grand total: {}".format(grand_total),
    ]
    lines.append(" | ".join(summary))
    return lines


def main():
    samples = [
        0,
        1,
        3,
        5,
        12,
    ]
    for line in build_report(samples):
        print(line)
    print("list_of_squares(3) ->", list_of_squares(3))
    print("list_of_squares(0) ->", list_of_squares(0))


if __name__ == "__main__":
    main()

