PRESETS = {
    "exact": {
        "ignore_case": False,
        "ignore_spaces": False,
    },
    "letters": {
        "ignore_case": True,
        "ignore_spaces": True,
    },
    "spaceless": {
        "ignore_case": False,
        "ignore_spaces": True,
    },
}


def has_unique_chars(s):
    """Return True when every character in `s` occurs exactly once."""
    seen = set()
    for ch in s:
        if ch in seen:
            return False
        seen.add(ch)
    return True


def duplicate_chars(s):
    """Return the characters that occur more than once, in first-seen order."""
    counts = Counter(s)
    ordered = []
    for ch in s:
        if counts[ch] > 1 and ch not in ordered:
            ordered.append(ch)
    return ordered


def normalize(s, ignore_case=False, ignore_spaces=False):
    """Apply the comparison options to `s` before uniqueness testing."""
    if ignore_case:
        s = s.lower()
    if ignore_spaces:
        s = "".join(ch for ch in s if not ch.isspace())
    return s


def analyze(s, preset="exact"):
    """Build a report describing the uniqueness of `s` under a preset."""
    text = normalize(s, **PRESETS[preset])
    return {
        "original": s,
        "preset": preset,
        "compared": text,
        "unique": has_unique_chars(text),
        "duplicates": duplicate_chars(text),
        "distinct": len(set(text)),
    }


def format_report(report):
    verdict = "unique" if report["unique"] else "not unique"
    parts = [
        "{!r} [{}] -> {}".format(report["original"], report["preset"], verdict),
        "distinct={}".format(report["distinct"]),
    ]
    if report["duplicates"]:
        parts.append("repeats=" + ",".join(report["duplicates"]))
    if report["compared"] != report["original"]:
        parts.append("compared={!r}".format(report["compared"]))
    return " | ".join(parts)


