BEATS = {
    'rock': 'scissors',
    'paper': 'rock',
    'scissors': 'paper',
}

ALIASES = {
    'r': 'rock',
    'p': 'paper',
    's': 'scissors',
}

RESULTS = {
    'tie': "It's a tie!",
    'player1': 'Player 1 wins!',
    'player2': 'Player 2 wins!',
}


def normalize_choice(choice):
    if not isinstance(choice, str):
        raise TypeError(f'choice must be a string, got {choice!r}')
    cleaned = choice.strip().lower()
    cleaned = ALIASES.get(cleaned, cleaned)
    if cleaned not in BEATS:
        raise ValueError(f'invalid choice: {choice!r}')
    return cleaned


def decide(first, second):
    if first == second:
        return 'tie'
    if BEATS[first] == second:
        return 'player1'
    return 'player2'


def rock_paper_scissors(player1_choice, player2_choice):
    first = normalize_choice(player1_choice)
    second = normalize_choice(player2_choice)
    return RESULTS[decide(first, second)]


def play_rounds(rounds):
    tally = {
        'player1': 0,
        'player2': 0,
        'tie': 0,
    }
    outcomes = []
    for p1, p2 in rounds:
        first = normalize_choice(p1)
        second = normalize_choice(p2)
        key = decide(first, second)
        tally[key] += 1
        outcomes.append((first, second, RESULTS[key]))
    return outcomes, tally


def format_report(outcomes, tally):
    lines = ['Round-by-round results:']
    for index, (p1, p2, verdict) in enumerate(outcomes, start=1):
        lines.append('  {}. {:<8} vs {:<8} -> {}'.format(index, p1, p2, verdict))
    lines.append('Score: Player 1 = {}, Player 2 = {}, ties = {}'.format(
        tally['player1'],
        tally['player2'],
        tally['tie'],
    ))
    if tally['player1'] > tally['player2']:
        lines.append('Match winner: Player 1')
    elif tally['player2'] > tally['player1']:
        lines.append('Match winner: Player 2')
    else:
        lines.append('Match winner: nobody, the match is drawn')
    return '\n'.join(lines)


def main():
    rounds = [
        ('rock', 'scissors'),
        ('paper', 'rock'),
        ('Scissors', 'ROCK'),
        ('p', 'p'),
        ('rock', 'paper'),
    ]
    outcomes, tally = play_rounds(rounds)
    print(format_report(outcomes, tally))


if __name__ == '__main__':
    main()

