ERROR_MESSAGES = {
    "type": "event times must be integers",
    "order": "event start must be before its end",
}

REPORT_TEMPLATES = {
    "free": "{request}: free",
    "conflict": "{request}: conflicts with {clashes} (try {options})",
}


def validate_interval(start, end):
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError(ERROR_MESSAGES["type"])
    if start >= end:
        raise ValueError(ERROR_MESSAGES["order"])
    return (start, end)


def normalize_schedule(schedule):
    return sorted(validate_interval(start, end) for start, end in schedule)


def has_conflict(schedule, new_event_start, new_event_end):
    start, end = validate_interval(new_event_start, new_event_end)
    for existing_start, existing_end in normalize_schedule(schedule):
        if start < existing_end and existing_start < end:
            return True
    return False


def conflicting_events(schedule, new_event_start, new_event_end):
    start, end = validate_interval(new_event_start, new_event_end)
    return [
        (existing_start, existing_end)
        for existing_start, existing_end in normalize_schedule(schedule)
        if start < existing_end and existing_start < end
    ]


def free_gaps(schedule, day_start, day_end):
    validate_interval(day_start, day_end)
    blocks = [
        (day_start, day_start),
        *normalize_schedule(schedule),
        (day_end, day_end),
    ]
    gaps = []
    cursor = day_start
    for start, end in blocks:
        limit = min(start, day_end)
        if cursor < limit:
            gaps.append((cursor, limit))
        cursor = max(cursor, end)
    return gaps


def format_interval(interval):
    return "{}-{}".format(*interval)


def format_report(report):
    request = format_interval(report["request"])
    if not report["conflict"]:
        return REPORT_TEMPLATES["free"].format(request=request)
    return REPORT_TEMPLATES["conflict"].format(
        request=request,
        clashes=", ".join(format_interval(event) for event in report["clashes"]),
        options=", ".join(format_interval(gap) for gap in report["alternatives"]),
    )


def describe_request(schedule, new_event_start, new_event_end, day_bounds):
    clashes = conflicting_events(schedule, new_event_start, new_event_end)
    return {
        "request": (new_event_start, new_event_end),
        "conflict": bool(clashes),
        "clashes": clashes,
        "alternatives": free_gaps(schedule, *day_bounds),
    }


def summarize(schedule, requests, day_bounds):
    reports = [describe_request(schedule, s, e, day_bounds) for s, e in requests]
    return {
        "requested": len(reports),
        "conflicts": sum(1 for report in reports if report["conflict"]),
        "lines": [format_report(report) for report in reports],
    }


def main():
    schedule = [
        (1, 5),
        (10, 15),
        (16, 18),
    ]
    requests = [
        (3, 7),
        (6, 8),
        (14, 17),
    ]
    summary = summarize(schedule, requests, (0, 24))
    for line in summary["lines"]:
        print(line)
    print("{} of {} requests conflict".format(summary["conflicts"], summary["requested"]))


if __name__ == "__main__":
    main()

