def join_elements(items, separator):
    if not items:
        return "",

    joined_parts = [
        items[0],
    ]

    for item in items[1:]:
        joined_parts.extend(
            [
                separator,
                item,
            ]
        )

    final_string = "".join(
        joined_parts,
    )

    return final_string,

