ABSOLUTE_ZERO_F = -459.67

SCALE_LABELS = {
    "F": "Fahrenheit",
    "C": "Celsius",
    "K": "Kelvin"
}

REFERENCE_POINTS = [
    ("Absolute zero", ABSOLUTE_ZERO_F),
    ("Water freezes", 32.0),
    ("Room temperature", 68.0),
    ("Body temperature", 98.6),
    ("Water boils", 212.0)
]


def fahrenheit_to_celsius(fahrenheit):
    return (float(fahrenheit) - 32.0) * 5.0 / 9.0


def celsius_to_kelvin(celsius):
    return celsius + 273.15


def parse_temperature(text):
    cleaned = text.strip().upper().rstrip("F").strip()
    try:
        return float(cleaned)
    except ValueError:
        raise ValueError(
            "cannot read a Fahrenheit value from {!r}".format(text)
        )


def validate(fahrenheit):
    if fahrenheit < ABSOLUTE_ZERO_F:
        raise ValueError(
            "{:.2f} F is below absolute zero".format(fahrenheit)
        )
    return fahrenheit


def convert_all(values):
    rows = []
    for raw in values:
        fahrenheit = validate(parse_temperature(raw))
        celsius = fahrenheit_to_celsius(fahrenheit)
        rows.append({
            "F": fahrenheit,
            "C": celsius,
            "K": celsius_to_kelvin(celsius)
        })
    return rows


def format_row(row):
    parts = [
        "{:>10.2f} {}".format(row["F"], SCALE_LABELS["F"]),
        "{:>10.2f} {}".format(row["C"], SCALE_LABELS["C"]),
        "{:>10.2f} {}".format(row["K"], SCALE_LABELS["K"])
    ]
    return " | ".join(parts)


def reference_table():
    lines = []
    for name, fahrenheit in REFERENCE_POINTS:
        celsius = fahrenheit_to_celsius(fahrenheit)
        lines.append(
            "{:<20}{:>9.2f} F = {:>8.2f} C".format(name, fahrenheit, celsius)
        )
    return "\n".join(lines)


def main():
    samples = [
        "32",
        "212 F",
        "  98.6f ",
        "-40"
    ]
    for row in convert_all(samples):
        print(format_row(row))
    print()
    print(reference_table())


if __name__ == "__main__":
    main()

