import sys

FIELD_ORDER = [
    "only_in_first",
    "only_in_second",
    "shared",
    "symmetric",
    "disjoint",
]

FIELD_LABELS = {
    "only_in_first": "only in first",
    "only_in_second": "only in second",
    "shared": "shared",
    "symmetric": "symmetric difference",
    "disjoint": "disjoint",
}

DEMO_CASES = [
    ("numbers", [1, 2, 3, 4], [3, 4, 5, 6]),
    ("letters", ['a', 'b'], ['c', 'd']),
    ("repeats", [1, 1, 2, 2, 3], [2]),
    ("empty second", ['x', 'y'], []),
    ("nested", [[1], [2], [3]], [[2]]),
]


def list_difference(list1, list2):
    """Return the elements of list1 that do not appear in list2."""
    try:
        excluded = set(list2)
    except TypeError:
        excluded = list2
    difference_list = [item for item in list1 if item not in excluded]
    return difference_list


def symmetric_difference(list1, list2):
    """Elements present in exactly one of the two lists, first list first."""
    return list_difference(list1, list2) + list_difference(list2, list1)


def difference_summary(list1, list2):
    """Describe the relationship between two lists as a dictionary."""
    only_first = list_difference(list1, list2)
    shared = list_difference(list1, only_first)
    return {
        "only_in_first": only_first,
        "only_in_second": list_difference(list2, list1),
        "shared": shared,
        "symmetric": symmetric_difference(list1, list2),
        "disjoint": len(shared) == 0,
    }


def format_summary(name, summary):
    """Render one summary dictionary as a block of aligned text lines."""
    width = max(len(label) for label in FIELD_LABELS.values())
    lines = [
        "{}:".format(name),
    ]
    for key in FIELD_ORDER:
        label = FIELD_LABELS[key].rjust(width)
        lines.append("  {}  {}".format(label, summary[key]))
    return "\n".join(lines)


def format_report(cases):
    """Render a block per case, separated by blank lines."""
    blocks = [format_summary(n, difference_summary(a, b)) for n, a, b in cases]
    return "\n\n".join(blocks)


def parse_items(text):
    """Split a comma separated argument into a list of trimmed items."""
    return [chunk.strip() for chunk in text.split(",") if chunk.strip()]


def main(argv):
    if len(argv) == 3:
        cases = [
            ("command line", parse_items(argv[1]), parse_items(argv[2])),
        ]
    else:
        cases = DEMO_CASES
    print(format_report(cases))


if __name__ == "__main__":
    main(sys.argv)

