def nth_fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1

    fib_numbers = [
        0,
        1,
    ]

    for i in range(2, n + 1):
        next_fib = fib_numbers[i - 1] + fib_numbers[i - 2]
        fib_numbers.append(
            next_fib,
        )

    return fib_numbers[n]

def _test_fibonacci():
    test_cases = [
        (0, 0,),
        (1, 1,),
        (2, 1,),
        (3, 2,),
        (4, 3,),
        (5, 5,),
        (6, 8,),
        (10, 55,),
    ]

    for input_n, expected_output in test_cases:
        actual_output = nth_fibonacci(
            input_n,
        )
        assert actual_output == expected_output, (
            f"Input: {input_n}, Expected: {expected_output}, Got: {actual_output}",
        )
    print(
        "All tests passed!",
    )

if __name__ == "__main__":
    _test_fibonacci()

