import argparse
import os
import sys

READ_OPTIONS = {
    "encoding": "utf-8",
    "errors": "replace",
}


def count_file_lines(filepath):
    """Return the number of lines in the text file at filepath."""
    line_count = 0
    with open(filepath, "r", **READ_OPTIONS) as handle:
        for _line in handle:
            line_count += 1
    return line_count


def file_stats(filepath):
    """Collect line, word and character counts for a single file."""
    lines = 0
    words = 0
    chars = 0
    with open(filepath, "r", **READ_OPTIONS) as handle:
        for line in handle:
            lines += 1
            words += len(line.split())
            chars += len(line)
    return {
        "path": filepath,
        "lines": lines,
        "words": words,
        "chars": chars,
    }


def collect(paths):
    """Return stats for readable files and messages for the unusable ones."""
    reports = []
    problems = []
    for path in paths:
        if not os.path.isfile(path):
            problems.append("not a file: {0}".format(path))
        elif not os.access(path, os.R_OK):
            problems.append("not readable: {0}".format(path))
        else:
            reports.append(file_stats(path))
    return reports, problems


def format_table(reports):
    """Render the collected stats as aligned text rows, with a total line."""
    header = [
        "lines",
        "words",
        "chars",
        "file",
    ]
    rows = [header]
    for report in reports:
        rows.append([
            str(report["lines"]),
            str(report["words"]),
            str(report["chars"]),
            report["path"],
        ])
    if len(reports) > 1:
        rows.append([
            str(sum(r["lines"] for r in reports)),
            str(sum(r["words"] for r in reports)),
            str(sum(r["chars"] for r in reports)),
            "total",
        ])
    widths = [max(len(row[i]) for row in rows) for i in range(len(header))]
    return "\n".join(
        "  ".join(cell.rjust(widths[i]) for i, cell in enumerate(row))
        for row in rows
    )


def main(argv=None):
    parser = argparse.ArgumentParser(description="Count lines in text files.")
    parser.add_argument("files", nargs="+", help="paths of files to measure")
    parser.add_argument(
        "-l",
        "--lines-only",
        action="store_true",
        help="print just the line count of each file",
    )
    args = parser.parse_args(argv)
    reports, problems = collect(args.files)
    if args.lines_only:
        for report in reports:
            print(report["lines"], report["path"])
    elif reports:
        print(format_table(reports))
    for problem in problems:
        print(problem, file=sys.stderr)
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())

