def harmonic_mean(numbers):
    if not numbers:
        raise ValueError(
            "Input list cannot be empty",
        )

    reciprocals = [
        1 / num
        for num in numbers
    ]

    sum_reciprocals = sum(
        reciprocals,
    )

    num_elements = len(
        numbers,
    )

    arithmetic_mean_of_reciprocals = (
        sum_reciprocals / num_elements
    )

    harmonic_mean_value = (
        1 / arithmetic_mean_of_reciprocals
    )

    return (
        harmonic_mean_value
    )

