ALERT_STATUSES = [
    "out of stock",
    "low",
]


def classify(quantity, low_threshold=3):
    """Map a quantity onto a short status label."""
    bands = [
        (0, "out of stock"),
        (low_threshold, "low"),
    ]
    for limit, status in bands:
        if quantity <= limit:
            return status
    return "ok"


def summarize(stock_levels, low_threshold=3):
    """Group the checked items by their stock status."""
    summary = {
        "out of stock": [],
        "low": [],
        "ok": [],
    }
    for item, quantity in stock_levels.items():
        summary[classify(quantity, low_threshold)].append(item)
    for bucket in summary.values():
        bucket.sort()
    return summary


def check_stock(inventory, items_to_check):
    """Return the available quantity for each requested item (0 if absent)."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict of item -> quantity")
    if not isinstance(items_to_check, list):
        raise TypeError("items_to_check must be a list of item names")
    return {item: inventory.get(item, 0) for item in items_to_check}


def format_report(stock_levels, low_threshold=3):
    """Render the stock levels and their grouping as printable lines."""
    width = max([4] + [len(name) for name in stock_levels])
    columns = [
        ("ITEM", "<" + str(width)),
        ("QTY", ">5"),
        ("STATUS", ""),
    ]
    row = "  ".join(
        "{" + str(index) + ":" + columns[index][1] + "}"
        for index in range(len(columns))
    )
    lines = [
        row.format(*[column[0] for column in columns]),
        "-" * (width + 16),
    ]
    for item in sorted(stock_levels):
        quantity = stock_levels[item]
        lines.append(row.format(item, quantity, classify(quantity, low_threshold)))
    summary = summarize(stock_levels, low_threshold)
    for status in ALERT_STATUSES:
        if summary[status]:
            lines.append(status + ": " + ", ".join(summary[status]))
    return lines


def main():
    inventory = {
        "apple": 10,
        "banana": 5,
        "flour": 2,
        "sugar": 0,
    }
    requests = [
        ["apple", "orange"],
        ["milk"],
        ["apple", "banana", "flour", "sugar", "yeast"],
    ]
    for items_to_check in requests:
        stock_levels = check_stock(inventory, items_to_check)
        print(stock_levels)
        for line in format_report(stock_levels):
            print(line)
        print()


if __name__ == "__main__":
    main()

