PUNCTUATION = ".,;:!?\"'()[]"

SAMPLE_TEXTS = [
    "This is a test sentence.",
    "  Hello   world  ",
    "the cat sat on the mat, the mat was flat",
]


def count_words(text):
    """Return the number of space-separated words in text."""
    if not isinstance(text, str):
        raise TypeError(
            "count_words() expects a string, got %s" % type(text).__name__,
        )
    return len(text.split())


def normalise(word):
    """Strip surrounding punctuation from a word and lower-case it."""
    return word.strip(PUNCTUATION).lower()


def word_frequencies(text):
    """Map each normalised word to how many times it occurs in text."""
    counts = {}
    for word in text.split():
        key = normalise(word)
        if key:
            counts[key] = counts.get(key, 0) + 1
    return counts


def longest_words(text, limit=3):
    """Return the longest distinct words of text, longest first."""
    words = sorted(
        {normalise(word) for word in text.split()} - {""},
        key=lambda word: (-len(word), word),
    )
    return words[:limit]


def summarise(text):
    """Build a small report describing the words of text."""
    return {
        "text": text,
        "word_count": count_words(text),
        "longest": longest_words(text),
        "frequencies": word_frequencies(text),
    }


def report_rows(summary):
    """Turn a report from summarise() into (label, value) pairs."""
    rows = [
        ("text", repr(summary["text"])),
        ("word count", str(summary["word_count"])),
        ("unique words", str(len(summary["frequencies"]))),
    ]
    longest = summary["longest"]
    if longest:
        rows.append(("longest", ", ".join(longest)))
    repeated = sorted(word for word, n in summary["frequencies"].items() if n > 1)
    if repeated:
        rows.append(("repeated", ", ".join(repeated)))
    return rows


def format_summary(summary):
    """Render a report produced by summarise() as aligned lines."""
    rows = report_rows(summary)
    width = max(len(label) for label, _value in rows)
    return ["%-*s : %s" % (width, label, value) for label, value in rows]


def main():
    for text in SAMPLE_TEXTS:
        for line in format_summary(summarise(text)):
            print(line)
        print("-" * 32)


if __name__ == "__main__":
    main()

