VALID_OPERATIONS = {
    "push",
    "pop",
}


def simulate_stack(stack, operation, item=None):
    """Perform a single stack operation in place and return its result."""
    if not isinstance(stack, list):
        raise TypeError("stack must be a list")
    if not isinstance(operation, str):
        raise TypeError("operation must be a string")

    op = operation.strip().lower()
    if op not in VALID_OPERATIONS:
        raise ValueError("unsupported operation: {!r}".format(operation))

    if op == "push":
        stack.append(item)
        return stack

    if not stack:
        return None
    return stack.pop()


def run_script(stack, script):
    """Apply a sequence of (operation, item) pairs, recording each step."""
    records = []
    for step, (operation, item) in enumerate(script, start=1):
        result = simulate_stack(stack, operation, item)
        records.append({
            "step": step,
            "operation": operation.strip().lower(),
            "item": item,
            "result": result,
            "stack": list(stack),
        })
    return records


def format_record(record):
    """Render one step record as a fixed-width table row."""
    if record["operation"] == "push":
        detail = repr(record["item"])
        outcome = "ok"
    else:
        detail = "-"
        outcome = "empty" if record["result"] is None else repr(record["result"])

    columns = [
        "{:>4}".format(record["step"]),
        "{:<6}".format(record["operation"]),
        "{:<8}".format(detail),
        "{:<8}".format(outcome),
        repr(record["stack"]),
    ]
    return " | ".join(columns)


def summarize(records):
    """Count how the script used the stack."""
    return {
        "steps": len(records),
        "pushes": sum(1 for r in records if r["operation"] == "push"),
        "pops": sum(1 for r in records if r["operation"] == "pop"),
        "underflows": sum(
            1 for r in records if r["operation"] == "pop" and r["result"] is None
        ),
    }


def main():
    stack = [1, 2]
    script = [
        ("push", 3),
        ("pop", None),
        ("pop", None),
        ("pop", None),
        ("pop", None),
        ("push", "a"),
    ]
    records = run_script(stack, script)

    header = [
        "{:>4}".format("step"),
        "{:<6}".format("op"),
        "{:<8}".format("item"),
        "{:<8}".format("result"),
        "stack",
    ]
    print(" | ".join(header))
    for record in records:
        print(format_record(record))

    stats = summarize(records)
    print("steps={steps} pushes={pushes} pops={pops} underflows={underflows}".format(**stats))
    print("final stack:", stack)


if __name__ == "__main__":
    main()

