import re
from collections import Counter

MENTION_PATTERN = re.compile(r"(?<![A-Za-z0-9_@.])@([A-Za-z0-9_]+)")

SAMPLE_TEXTS = [
    "Hello @user1, how are you @user2?",
    "No mentions here.",
    "@ada and @grace built it, thanks @ada!",
    "Email me at nobody@example.com or ping @bob_99",
]


def extract_mentions(text):
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    mentions_list = MENTION_PATTERN.findall(text)
    return mentions_list


def dedupe(names):
    seen = []
    for name in names:
        if name not in seen:
            seen.append(name)
    return seen


def summarize(text):
    mentions = extract_mentions(text)
    return {
        "text": text,
        "total": len(mentions),
        "unique": dedupe(mentions),
    }


def mention_counts(texts):
    counter = Counter()
    for text in texts:
        counter.update(extract_mentions(text))
    return counter


def mention_stats(texts, counter):
    return {
        "texts": len(texts),
        "total": sum(counter.values()),
        "distinct": len(counter),
    }


def format_summary(summary):
    if summary["total"] == 0:
        listed = "(none)"
    else:
        listed = ", ".join("@" + name for name in summary["unique"])
    parts = [
        "text   : {0}".format(summary["text"]),
        "found  : {0}".format(summary["total"]),
        "unique : {0}".format(listed),
    ]
    return "\n".join(parts)


def describe_stats(stats):
    lines = [
        "texts scanned  : {0}".format(stats["texts"]),
        "mentions found : {0}".format(stats["total"]),
        "distinct users : {0}".format(stats["distinct"]),
    ]
    return "\n".join(lines)


def format_leaderboard(counter, limit=3):
    ranked = sorted(counter.items(), key=lambda item: (-item[1], item[0]))
    rows = [
        "{0:>2}. @{1} ({2})".format(rank, name, hits)
        for rank, (name, hits) in enumerate(ranked[:limit], start=1)
    ]
    return "\n".join(rows) if rows else "no mentions at all"


def build_report(texts):
    counter = mention_counts(texts)
    parts = [
        "MENTION REPORT",
        "=" * 40,
    ]
    for text in texts:
        parts.append(format_summary(summarize(text)))
        parts.append("-" * 40)
    parts.append(describe_stats(mention_stats(texts, counter)))
    parts.append("Most mentioned:")
    parts.append(format_leaderboard(counter))
    return "\n".join(parts)


def main():
    print(build_report(SAMPLE_TEXTS))


if __name__ == "__main__":
    main()

