import sys

DEFAULT_LIMITS = [
    3,
    0,
    6
]


def cubes_up_to(limit):
    """Return the cubes of every integer from 0 up to `limit` (inclusive)."""
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an int, got {!r}".format(limit))
    if limit < 0:
        raise ValueError("limit must be non-negative, got {}".format(limit))
    cubes_list = [n ** 3 for n in range(limit + 1)]
    return cubes_list


def summarize(cubes_list):
    """Collect a few useful facts about a list of cubes."""
    return {
        "count": len(cubes_list),
        "largest": cubes_list[-1],
        "total": sum(cubes_list),
        "odd_cubes": [value for value in cubes_list if value % 2]
    }


def growth(cubes_list):
    """Describe how fast the cubes grow from one entry to the next."""
    deltas = [later - earlier for earlier, later in zip(cubes_list, cubes_list[1:])]
    return {
        "deltas": deltas,
        "mean_delta": sum(deltas) / len(deltas) if deltas else 0.0
    }


def format_table(cubes_list):
    """Render the cubes as an aligned 'n -> n**3' table."""
    width = max(len(str(len(cubes_list) - 1)), 1)
    lines = [
        "{:>{w}} -> cube".format("n", w=width),
        "-" * (width + 8)
    ]
    lines.extend(
        "{n:>{w}} -> {cube}".format(n=n, cube=cube, w=width)
        for n, cube in enumerate(cubes_list)
    )
    return "\n".join(lines)


def report(limit):
    """Build a multi-line report for a single limit."""
    cubes_list = cubes_up_to(limit)
    facts = summarize(cubes_list)
    change = growth(cubes_list)
    lines = [
        "limit = {}".format(limit),
        format_table(cubes_list),
        "count: {count}, largest: {largest}, total: {total}".format(**facts),
        "odd cubes: {}".format(facts["odd_cubes"]),
        "deltas: {} (mean {:.2f})".format(change["deltas"], change["mean_delta"])
    ]
    return "\n".join(lines)


def parse_limits(args):
    """Turn command-line arguments into limits, falling back to the defaults."""
    if not args:
        return list(DEFAULT_LIMITS)
    return [int(arg) for arg in args]


def main(argv=None):
    limits = parse_limits(sys.argv[1:] if argv is None else argv)
    for limit in limits:
        print(report(limit))
        print()


if __name__ == "__main__":
    main()

