import secrets
from collections import Counter

DIGITS = "0123456789"

WEAK_PATTERNS = (
    "0000",
    "1111",
    "1234",
    "4321",
    "1212",
)

POLICY = {
    "min_length": 3,
    "max_length": 12,
    "max_repeats": 3,
}

DEMO_LENGTHS = (
    4,
    6,
    8,
)


def generate_pin(length):
    """Return a random numeric PIN of the requested length as a string."""
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an int")
    if length < 1:
        raise ValueError("length must be at least 1")
    return "".join(secrets.choice(DIGITS) for _ in range(length))


def pin_stats(pin):
    counts = Counter(pin)
    digit, repeats = counts.most_common(1)[0]
    return {
        "length": len(pin),
        "distinct": len(counts),
        "most_common_digit": digit,
        "most_common_count": repeats,
    }


def is_acceptable(pin):
    stats = pin_stats(pin)
    if not POLICY["min_length"] <= stats["length"] <= POLICY["max_length"]:
        return False
    if stats["most_common_count"] > POLICY["max_repeats"]:
        return False
    return all(pattern not in pin for pattern in WEAK_PATTERNS)


def generate_strong_pin(length, attempts=50):
    for _ in range(attempts):
        candidate = generate_pin(length)
        if is_acceptable(candidate):
            return candidate
    raise RuntimeError("could not generate an acceptable PIN")


def format_report(pin):
    stats = pin_stats(pin)
    fields = [
        ("pin", pin),
        ("length", stats["length"]),
        ("distinct digits", stats["distinct"]),
        ("acceptable", is_acceptable(pin)),
    ]
    return " | ".join("{}={}".format(name, value) for name, value in fields)


def main():
    for length in DEMO_LENGTHS:
        print(format_report(generate_pin(length)))
        print("strong:", format_report(generate_strong_pin(length)))


if __name__ == "__main__":
    main()

