def _dimensions(matrix):
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    widths = set()
    for row in matrix:
        if not isinstance(row, list):
            raise TypeError("matrix rows must be lists")
        widths.add(len(row))
    if len(widths) > 1:
        raise ValueError("matrix rows must all have the same length")
    return (
        len(matrix),
        widths.pop() if widths else 0,
    )


def validate_shapes(matrix1, matrix2):
    shapes = [
        _dimensions(matrix1),
        _dimensions(matrix2),
    ]
    if shapes[0] != shapes[1]:
        raise ValueError("shape mismatch: {0}x{1} vs {2}x{3}".format(
            shapes[0][0],
            shapes[0][1],
            shapes[1][0],
            shapes[1][1],
        ))
    return shapes[0]


def matrix_subtract(matrix1, matrix2):
    validate_shapes(matrix1, matrix2)
    result_matrix = []
    for row1, row2 in zip(matrix1, matrix2):
        result_matrix.append([a - b for a, b in zip(row1, row2)])
    return result_matrix


def _format_number(value):
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_matrix(matrix):
    if not matrix:
        return "[]"
    cells = [[_format_number(value) for value in row] for row in matrix]
    width = max(
        (len(text) for row in cells for text in row),
        default=0,
    )
    lines = ["[" + "  ".join(text.rjust(width) for text in row) + "]" for row in cells]
    return "\n".join(lines)


def report(matrix1, matrix2):
    difference = matrix_subtract(matrix1, matrix2)
    blocks = [
        ("minuend", matrix1),
        ("subtrahend", matrix2),
        ("difference", difference),
    ]
    sections = [label + ":\n" + format_matrix(matrix) for label, matrix in blocks]
    return "\n".join(sections)


def main():
    cases = [
        ([[1, 2], [3, 4]], [[1, 1], [1, 1]]),
        ([[5, 0]], [[1, -1]]),
        (
            [[2.5, -3, 10], [0, 7, 1.25]],
            [[0.5, 3, 4], [-2, 7, 0.25]],
        ),
    ]
    for index, (left, right) in enumerate(cases, start=1):
        print("case %d" % index)
        print(report(left, right))
        print()


if __name__ == "__main__":
    main()

