HEADERS = [
    "input",
    "distinct",
    "third largest",
    "note",
]

SAMPLES = [
    [3, 2, 1, 5, 4],
    [1, 1, 2],
    [7],
    [10, 10, 9, 9, 8, 8, 7],
    [-1, -5, -3, -3, -2],
]


def validate_numbers(numbers):
    """Return the input as a list of ints, raising on malformed input."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of integers")
    cleaned = []
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(
                "numbers[{0}] is not an integer: {1!r}".format(
                    index,
                    value,
                )
            )
        cleaned.append(value)
    if not cleaned:
        raise ValueError("numbers must contain at least one integer")
    return cleaned


def distinct_descending(numbers):
    """Distinct values of the list, largest first."""
    return sorted(set(numbers), reverse=True)


def find_third_largest(numbers):
    """Third largest distinct value, or the largest if fewer than three exist."""
    ranked = distinct_descending(validate_numbers(numbers))
    if len(ranked) < 3:
        return ranked[0]
    return ranked[2]


def summarize(numbers):
    """Build a small report describing the ranking of one input list."""
    values = validate_numbers(numbers)
    ranked = distinct_descending(values)
    note = ""
    if len(ranked) < 3:
        note = "fewer than 3 distinct, returned largest"
    return {
        "input": list(values),
        "distinct": ranked,
        "third_largest": find_third_largest(values),
        "note": note,
    }


def format_row(summary):
    """Turn a report dict into the cells of one table row."""
    return [
        str(summary["input"]),
        str(summary["distinct"]),
        str(summary["third_largest"]),
        summary["note"],
    ]


def format_table(summaries):
    """Render reports as aligned text lines, header first."""
    rows = [HEADERS]
    rows.extend(format_row(summary) for summary in summaries)
    widths = [max(len(row[i]) for row in rows) for i in range(len(HEADERS))]
    lines = []
    for row in rows:
        cells = [cell.ljust(width) for cell, width in zip(row, widths)]
        lines.append(" | ".join(cells).rstrip())
    return lines


def main():
    summaries = [summarize(sample) for sample in SAMPLES]
    for line in format_table(summaries):
        print(line)


if __name__ == "__main__":
    main()

