from collections import OrderedDict


def normalize(word):
    """Return the canonical anagram key for a word (case- and space-insensitive)."""
    return "".join(
        sorted(
            char.lower()
            for char in word
            if char.isalnum()
        ),
    )


def validate_words(words):
    """Return the input as a list of strings, rejecting anything else."""
    if isinstance(words, str):
        raise TypeError("expected a list of words, got a single string")
    checked = []
    for index, word in enumerate(words):
        if not isinstance(word, str):
            raise TypeError(
                "word at index {0} is not a string: {1!r}".format(
                    index,
                    word,
                ),
            )
        checked.append(word)
    return checked


def group_anagrams(words):
    """Group the given words into lists of mutual anagrams."""
    buckets = OrderedDict()
    for word in validate_words(words):
        buckets.setdefault(normalize(word), []).append(word)
    return list(buckets.values())


def sort_groups(anagram_groups):
    """Order the groups by size (largest first) and their words alphabetically."""
    ordered = [sorted(group) for group in anagram_groups]
    ordered.sort(
        key=lambda group: (
            -len(group),
            group[0],
        ),
    )
    return ordered


def format_report(anagram_groups):
    """Render the groups as one readable line per group."""
    lines = []
    for group in sort_groups(anagram_groups):
        lines.append(
            "{0:>2} | {1:<10} | {2}".format(
                len(group),
                normalize(group[0]) or "-",
                ", ".join(group),
            ),
        )
    return "\n".join(lines)


def summarize(anagram_groups):
    """Return counts describing a grouping result."""
    groups = sort_groups(anagram_groups)
    return {
        "groups": len(groups),
        "words": sum(len(group) for group in groups),
        "largest": len(groups[0]) if groups else 0,
        "singletons": sum(1 for group in groups if len(group) == 1),
    }


def main():
    samples = [
        ['eat', 'tea', 'tan', 'ate', 'nat', 'bat'],
        ['a', 'b'],
        ['Listen', 'Silent', 'enlist', 'Google', 'gooegl', 'cat'],
    ]
    for words in samples:
        groups = group_anagrams(words)
        print("input:", words)
        print(format_report(groups))
        print(
            "groups: {groups}, words: {words}, "
            "largest: {largest}, singletons: {singletons}".format(
                **summarize(groups),
            ),
        )
        print()


if __name__ == "__main__":
    main()

