def validate_image(image_matrix):
    if not isinstance(image_matrix, list):
        raise TypeError("image_matrix must be a list of rows")
    widths = set()
    for y, row in enumerate(image_matrix):
        if not isinstance(row, list):
            raise TypeError("row %d must be a list of pixels" % y)
        widths.add(len(row))
        for x, pixel in enumerate(row):
            if not isinstance(pixel, list) or len(pixel) != 3:
                raise ValueError("pixel (%d, %d) must be [R, G, B]" % (x, y))
            for channel in pixel:
                if not isinstance(channel, int) or not 0 <= channel <= 255:
                    raise ValueError(
                        "pixel (%d, %d) has a channel outside 0..255" % (x, y)
                    )
    if len(widths) > 1:
        raise ValueError("all rows must have the same width")


def to_grayscale(image_matrix):
    validate_image(image_matrix)
    return [
        [sum(pixel) // 3 for pixel in row]
        for row in image_matrix
    ]


def image_stats(grayscale_image):
    values = [value for row in grayscale_image for value in row]
    if not values:
        return {
            "pixels": 0,
            "minimum": None,
            "maximum": None,
            "mean": None
        }
    return {
        "pixels": len(values),
        "minimum": min(values),
        "maximum": max(values),
        "mean": sum(values) / len(values)
    }


def render_ascii(grayscale_image, ramp="@%#*+=-:. "):
    step = 256 / len(ramp)
    lines = []
    for row in grayscale_image:
        lines.append("".join(ramp[min(int(v / step), len(ramp) - 1)] for v in row))
    return "\n".join(lines)


def describe(name, image_matrix):
    gray = to_grayscale(image_matrix)
    stats = image_stats(gray)
    body = [
        "%s: %d x %d" % (name, len(gray[0]) if gray else 0, len(gray)),
        "  values: " + repr(gray),
        "  pixels: %d, min: %s, max: %s, mean: %s" % (
            stats["pixels"],
            stats["minimum"],
            stats["maximum"],
            stats["mean"]
        ),
        "  ascii:\n" + render_ascii(gray)
    ]
    return "\n".join(body)


def main():
    samples = [
        ("primaries", [[[255, 0, 0], [0, 255, 0]]]),
        ("single", [[[10, 20, 30]]]),
        ("gradient", [
            [[0, 0, 0], [64, 64, 64], [128, 128, 128], [255, 255, 255]],
            [[255, 255, 255], [128, 128, 128], [64, 64, 64], [0, 0, 0]]
        ])
    ]
    for name, matrix in samples:
        print(describe(name, matrix))
        print()


if __name__ == "__main__":
    main()

