def count_char(
    text,
    char_to_count,
):
    count = 0
    for char in text:
        if char == char_to_count:
            count += 1
    return count

def test_count_char():
    test_cases = [
        ('banana', 'a', 3,),
        ('Mississippi', 's', 4,),
        ('hello world', 'l', 3,),
        ('python', 'z', 0,),
        ('', 'a', 0,),
        ('aaaaa', 'a', 5,),
        ('AbcAbc', 'A', 2,),
    ]

    for text, char_to_count, expected_count in test_cases:
        actual_count = count_char(
            text,
            char_to_count,
        )
        assert actual_count == expected_count, (
            f"For text='{text}', char='{char_to_count}', "
            f"Expected: {expected_count}, Got: {actual_count}",
        )
    print(
        "All test cases passed!",
    )

if __name__ == '__main__':
    test_count_char()

