def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return float(celsius) * 9 / 5 + 32


REFERENCE_POINTS = {
    "absolute zero": -273.15,
    "water freezes": 0.0,
    "human body": 37.0,
    "water boils": 100.0,
}

SCALE_LABELS = (
    "Celsius",
    "Fahrenheit",
)


def parse_celsius(text):
    """Read a Celsius value from a string, tolerating a trailing unit."""
    cleaned = text.strip().rstrip("Cc").rstrip("\u00b0").strip()
    if not cleaned:
        raise ValueError("no temperature given")
    try:
        return float(cleaned)
    except ValueError:
        raise ValueError("cannot read %r as a Celsius value" % text)


def convert_all(values):
    """Convert an iterable of Celsius values into (C, F) pairs."""
    return [
        (value, celsius_to_fahrenheit(value))
        for value in values
    ]


def format_row(celsius, fahrenheit, widths):
    cells = [
        "{0:.2f}".format(celsius).rjust(widths[0]),
        "{0:.2f}".format(fahrenheit).rjust(widths[1]),
    ]
    return " | ".join(cells)


def build_table(pairs):
    """Render conversion pairs as a small aligned text table."""
    widths = [
        max(len(SCALE_LABELS[0]), 9),
        max(len(SCALE_LABELS[1]), 9),
    ]
    lines = [
        " | ".join(
            [
                SCALE_LABELS[0].rjust(widths[0]),
                SCALE_LABELS[1].rjust(widths[1]),
            ]
        ),
        "-+-".join("-" * width for width in widths),
    ]
    for celsius, fahrenheit in pairs:
        lines.append(format_row(celsius, fahrenheit, widths))
    return "\n".join(lines)


def describe_references():
    return [
        "{0}: {1:.2f} C = {2:.2f} F".format(
            name,
            celsius,
            celsius_to_fahrenheit(celsius),
        )
        for name, celsius in sorted(REFERENCE_POINTS.items(), key=lambda item: item[1])
    ]


def main():
    inputs = [
        "0",
        "100",
        "-40 C",
        "21.5\u00b0C",
    ]
    print(build_table(convert_all(parse_celsius(text) for text in inputs)))
    print()
    for line in describe_references():
        print(line)


if __name__ == "__main__":
    main()

