def is_perfect_number(number: int) -> bool:
    if number <= 1:
        return False

    divisors = [
        1,
    ]
    for i in range(
        2,
        int(number**0.5) + 1,
    ):
        if number % i == 0:
            divisors.append(
                i,
            )
            if i * i != number:
                divisors.append(
                    number // i,
                )

    sum_of_divisors = sum(
        divisors,
    )

    return sum_of_divisors == number

