from collections import Counter

SAMPLES = [
    "leetcode",
    "loveleetcode",
    "aabb",
    "",
    "swiss cheese",
    "z",
]

ROW = "{0:<16} {1:<26} distinct={2} unique_at={3}"


def char_counts(s):
    """Return a mapping from character to number of occurrences in s."""
    return Counter(s)


def first_unique_char(s):
    """Return the index of the first non-repeating character, or -1."""
    if not isinstance(s, str):
        raise TypeError("first_unique_char expects a string")
    counts = char_counts(s)
    for index, char in enumerate(s):
        if counts[char] == 1:
            return index
    return -1


def all_unique_indices(s):
    """Return every index whose character occurs exactly once in s."""
    counts = char_counts(s)
    return [index for index, char in enumerate(s) if counts[char] == 1]


def describe(s):
    """Build a record describing the unique-character analysis of s."""
    index = first_unique_char(s)
    return {
        "text": s,
        "index": index,
        "char": s[index] if index >= 0 else None,
        "unique_indices": all_unique_indices(s),
        "distinct": len(char_counts(s)),
    }


def summarize(records):
    """Aggregate a list of analysis records into overall figures."""
    return {
        "total": len(records),
        "with_unique": sum(1 for record in records if record["index"] >= 0),
        "longest": max((len(record["text"]) for record in records), default=0),
    }


def format_record(record):
    """Render one analysis record as a single readable line."""
    if record["index"] < 0:
        verdict = "no unique character"
    else:
        verdict = "index {0} -> {1!r}".format(
            record["index"],
            record["char"],
        )
    return ROW.format(
        repr(record["text"]),
        verdict,
        record["distinct"],
        record["unique_indices"],
    )


def format_summary(summary):
    """Render the aggregated figures as a closing line."""
    return "{0} samples, {1} with a unique character, longest={2}".format(
        summary["total"],
        summary["with_unique"],
        summary["longest"],
    )


def report(samples):
    """Analyse each sample string and return the formatted report lines."""
    records = [describe(sample) for sample in samples]
    lines = [format_record(record) for record in records]
    lines.append(format_summary(summarize(records)))
    return lines


def main():
    for line in report(SAMPLES):
        print(line)


if __name__ == "__main__":
    main()

