    for price, discount, expected in test_cases:
        result = calculate_discount_price(price, discount)
        assert result == expected, (
            f"For price={price}, discount={discount}, "
            f"Expected: {expected}, Got: {result}",
        )
        print(f"Test passed for {price}, {discount}: {result}",)

