def is_even(number):
    """Return True when the given integer is even."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("is_even() requires an int, got {!r}".format(number))
    return number % 2 == 0


def parse_numbers(text):
    """Turn a whitespace/comma separated string into a list of integers."""
    tokens = text.replace(",", " ").split()
    numbers = []
    for token in tokens:
        try:
            numbers.append(int(token))
        except ValueError:
            raise ValueError("not an integer: {!r}".format(token))
    return numbers


def split_by_parity(numbers):
    """Group the numbers into even and odd buckets."""
    buckets = {
        "even": [],
        "odd": [],
    }
    for number in numbers:
        key = "even" if is_even(number) else "odd"
        buckets[key].append(number)
    return buckets


def summarize(numbers):
    """Build a small report describing the parity of each number."""
    buckets = split_by_parity(numbers)
    return {
        "total": len(numbers),
        "even_count": len(buckets["even"]),
        "odd_count": len(buckets["odd"]),
        "even": buckets["even"],
        "odd": buckets["odd"],
    }


def format_report(summary):
    """Render a summary dict as lines of human readable text."""
    lines = [
        "numbers inspected: {}".format(summary["total"]),
        "even ({}): {}".format(
            summary["even_count"],
            ", ".join(str(n) for n in summary["even"]) or "-",
        ),
        "odd ({}): {}".format(
            summary["odd_count"],
            ", ".join(str(n) for n in summary["odd"]) or "-",
        ),
    ]
    return "\n".join(lines)


def main():
    samples = [
        "4 7",
        "0, 1, 2, 3, 10, -6, -9",
        "100 101 102",
    ]
    for sample in samples:
        numbers = parse_numbers(sample)
        print("input: {}".format(sample))
        print(format_report(summarize(numbers)))
        for number in numbers:
            print("  is_even({}) -> {}".format(number, is_even(number)))
        print()


if __name__ == "__main__":
    main()

