        key = str(permutation[0])
        groups.setdefault(key, []).append(permutation)
    return groups


def summarize(lst):
    """Collect the permutations of ``lst`` together with a few derived facts."""
    permutations = generate_permutations(lst)
    return {
        "input": list(lst),
        "total": count_permutations(lst),
        "permutations": permutations,
        "groups": group_by_first(permutations)
    }


def format_permutation(permutation):
    return "(" + ", ".join(str(item) for item in permutation) + ")"


def describe_group(key, permutations):
    return "  starts with {}: {}".format(
        key,
        " ".join(format_permutation(p) for p in permutations)
    )


def format_report(lst):
    """Build a human readable report about the permutations of ``lst``."""
    summary = summarize(lst)
    groups = summary["groups"]
    lines = [
        "input: {}".format(format_permutation(summary["input"])),
        "total: {}".format(summary["total"])
    ]
    lines.extend([
        "distinct leading elements: {}".format(len(groups)),
        "orderings listed: {}".format(len(summary["permutations"]))
    ])
    for key in sorted(groups):
        lines.append(describe_group(key, groups[key]))
    return "\n".join(lines)


def parse_tokens(tokens):
    """Turn command line tokens into numbers where that is possible."""
    values = []
    for token in tokens:
        for converter in CONVERTERS:
            try:
                values.append(converter(token))
                break
            except ValueError:
                continue
        else:
            values.append(token)
    return values


def main():
    arguments = sys.argv[1:]
    if not arguments:
        print("usage: permutations.py ITEM [ITEM ...]", file=sys.stderr)
        return 1
    print(format_report(parse_tokens(arguments)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

