    words = sentence.split(
        ' ',

    )

    reversed_words = list(
        reversed(words),

    )

    result = ' '.join(
        reversed_words,

    )

    special_punctuation = (
        '.',
        ',',
        '!',
        '?',
        ';',
        ':',
    )

    processed_parts = []
    for part in result.split():
        if part and part[-1] in special_punctuation and len(part) > 1:
            processed_parts.append(
                part[-1] + part[:-1],

            )
        else:
            processed_parts.append(
                part,

            )

    # The example output for 'Hello, world!' is 'world!, Hello,', 
    # which suggests punctuation moves with the word.
    # The example 'One. Two. Three.' -> 'Three. Two. One.' also suggests 
    # punctuation stays with its word.
    # The current implementation correctly handles this by splitting on spaces.
    # The `processed_parts` logic above would be needed if punctuation was to be detached.
    # Given the examples, we just need to join the reversed words.

    return ' '.join(
        reversed_words,

    )

