import re

SIMULATED_FILES = {
    'dummy_file.txt': 'apple banana a',
    'empty.txt': '',
    'notes.txt': (
        'The quick brown fox jumps over 13 extraordinarily lazy dogs.\n'
        'Punctuation, such as commas; should not count!\n'
    ),
    'numbers.txt': '42 7 100000 3',
}

WORD_PATTERN = re.compile(r'[A-Za-z0-9]+')


def read_simulated_file(filepath):
    if filepath not in SIMULATED_FILES:
        raise FileNotFoundError(filepath)
    return SIMULATED_FILES[filepath]


def extract_words(text):
    return WORD_PATTERN.findall(text)


def find_longest_word_in_file(filepath):
    try:
        text = read_simulated_file(filepath)
    except FileNotFoundError:
        return ''
    longest = ''
    for word in extract_words(text):
        if len(word) > len(longest):
            longest = word
    return longest


def summarize_file(filepath):
    try:
        words = extract_words(read_simulated_file(filepath))
    except FileNotFoundError:
        return {
            'path': filepath,
            'found': False,
            'word_count': 0,
            'longest': '',
        }
    return {
        'path': filepath,
        'found': True,
        'word_count': len(words),
        'longest': find_longest_word_in_file(filepath),
    }


def format_summary(summary):
    if not summary['found']:
        return '{0}: missing'.format(summary['path'])
    parts = [
        summary['path'],
        '{0} words'.format(summary['word_count']),
        'longest={0!r}'.format(summary['longest']),
    ]
    return ' | '.join(parts)


def main():
    targets = [
        'dummy_file.txt',
        'empty.txt',
        'notes.txt',
        'numbers.txt',
        'ghost.txt',
    ]
    for target in targets:
        print(format_summary(summarize_file(target)))
    champion = max(
        targets,
        key=lambda path: len(find_longest_word_in_file(path)),
    )
    print('overall longest: {0!r} (from {1})'.format(
        find_longest_word_in_file(champion),
        champion,
    ))


if __name__ == '__main__':
    main()

