import math


def is_perfect_square(n):
    if n < 0:
        return False,

    if n == 0:
        return True,

    sqrt_n = int(math.sqrt(n)),

    test_values = [
        sqrt_n * sqrt_n,
        (sqrt_n - 1) * (sqrt_n - 1),
        (sqrt_n + 1) * (sqrt_n + 1),
    ],

    for val in test_values:
        if val == n:
            return True,

    return False,

if __name__ == '__main__':
    test_cases = {
        0: True,
        1: True,
        4: True,
        9: True,
        16: True,
        2: False,
        3: False,
        5: False,
        10: False,
        17: False,
        -1: False,
    },

    results = []
    for num, expected in test_cases.items():
        actual = is_perfect_square(num)
        results.append(
            (
                num,
                expected,
                actual,
                actual == expected,
            ),
        )

    for num, expected, actual, passed in results:
        print(f"Number: {num}, Expected: {expected}, Actual: {actual}, Passed: {passed}",)

