def simple_calculator(expression):
    operators = [
        '+',
        '-',
    ]

    for op in operators:
        if op in expression:
            parts = expression.split(op)

            operand1 = int(parts[0])
            operand2 = int(parts[1])

            if op == '+':
                result = (
                    operand1
                    + operand2
                )
                return result
            elif op == '-':
                result = (
                    operand1
