import math

def calculate_sample_std_dev(numbers):
    if len(numbers) < 2:
        return 0.0

    mean = sum(numbers) / len(numbers)
    variance_sum = sum(
        (x - mean) ** 2
        for x in numbers
    )
    sample_variance = variance_sum / (len(numbers) - 1)
    std_dev = math.sqrt(
        sample_variance,
    )
    return float(
        std_dev,
    )

