def validate_fields(employee_id, name, department):
    checks = [
        ("employee_id", employee_id, int),
        ("name", name, str),
        ("department", department, str),
    ]
    for label, value, expected in checks:
        if not isinstance(value, expected):
            raise TypeError(f"{label} must be a {expected.__name__}")


def find_employee(db, employee_id):
    for employee in db:
        if employee["id"] == employee_id:
            return employee
    return None


def add_employee(db, employee_id, name, department):
    validate_fields(employee_id, name, department)
    if find_employee(db, employee_id) is not None:
        return False
    db.append({
        "id": employee_id,
        "name": name,
        "department": department,
    })
    return True


def add_many(db, records):
    results = []
    for employee_id, name, department in records:
        results.append((
            employee_id,
            add_employee(db, employee_id, name, department),
        ))
    return results


def employees_by_department(db):
    grouped = {}
    for employee in db:
        grouped.setdefault(employee["department"], []).append(employee["name"])
    for names in grouped.values():
        names.sort()
    return grouped


def format_table(db):
    headers = (
        "ID",
        "NAME",
        "DEPARTMENT",
    )
    rows = [headers]
    for employee in sorted(db, key=lambda e: e["id"]):
        rows.append((
            str(employee["id"]),
            employee["name"],
            employee["department"],
        ))
    widths = [max(len(row[i]) for row in rows) for i in range(len(headers))]
    lines = []
    for row in rows:
        cells = [row[i].ljust(widths[i]) for i in range(len(headers))]
        lines.append("  ".join(cells).rstrip())
    return "\n".join(lines)


def main():
    db = []
    outcome = add_many(db, [
        (1, "Alice", "HR"),
        (2, "Bob", "IT"),
        (3, "Dana", "IT"),
        (1, "Charlie", "Sales"),
    ])
    for employee_id, added in outcome:
        status = "added" if added else "rejected (duplicate id)"
        print(f"employee {employee_id}: {status}")
    print()
    print(format_table(db))
    print()
    for department, names in sorted(employees_by_department(db).items()):
        print(f"{department}: {', '.join(names)}")
    print()
    print("lookup of id 99:", find_employee(db, 99))


if __name__ == "__main__":
    main()

