QUADRANT_NAMES = {
    0: "on an axis",
    1: "quadrant I",
    2: "quadrant II",
    3: "quadrant III",
    4: "quadrant IV",
}

SAMPLE_POINTS = [
    (3, 5),
    (-2, 0),
    (-4.5, 1.25),
    (-1, -1),
    (7, -0.5),
    (0, 0),
]


def get_quadrant(x, y):
    """Return the quadrant (1-4) containing (x, y), or 0 if it is on an axis."""
    coordinates = (
        ("x", x),
        ("y", y),
    )
    for name, value in coordinates:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("coordinate {0} must be a real number".format(name))
    if x == 0 or y == 0:
        return 0
    if x > 0:
        return 1 if y > 0 else 4
    return 2 if y > 0 else 3


def parse_point(text):
    """Parse a point written as 'x,y' or 'x y' into a tuple of floats."""
    cleaned = text.replace(",", " ").split()
    if len(cleaned) != 2:
        raise ValueError("expected two coordinates, got {0!r}".format(text))
    return tuple(float(part) for part in cleaned)


def format_point(x, y):
    return "({0:g}, {1:g})".format(x, y)


def describe(x, y):
    quadrant = get_quadrant(x, y)
    return "{0} lies in {1}".format(
        format_point(x, y),
        QUADRANT_NAMES[quadrant],
    )


def summarize(points):
    """Count how many of the given points fall in each quadrant."""
    tally = dict.fromkeys(QUADRANT_NAMES, 0)
    for point in points:
        tally[get_quadrant(*point)] += 1
    return tally


def main():
    extra = [
        parse_point("2.5, -3"),
        parse_point("-8 -8"),
        parse_point("0 4"),
    ]
    for x, y in SAMPLE_POINTS + extra:
        print(describe(x, y))

    tally = summarize(SAMPLE_POINTS + extra)
    print("--- summary ---")
    for quadrant in sorted(tally):
        print("{0:<14} {1}".format(
            QUADRANT_NAMES[quadrant],
            tally[quadrant],
        ))


if __name__ == "__main__":
    main()

