import re
import sys


def normalize_bad_words(bad_words):
    return sorted(
        {word.strip().lower() for word in bad_words if word.strip()},
        key=len,
        reverse=True,
    )


def build_pattern(words):
    alternatives = "|".join(re.escape(word) for word in words)
    return re.compile(
        r"\b(?:" + alternatives + r")\b",
        re.IGNORECASE,
    )


def censor_text(text, bad_words):
    words = normalize_bad_words(bad_words)
    if not words:
        return text
    pattern = build_pattern(words)
    return pattern.sub(lambda match: "*" * len(match.group(0)), text)


def count_hits(text, bad_words):
    words = normalize_bad_words(bad_words)
    tally = {}
    if not words:
        return tally
    for match in build_pattern(words).finditer(text):
        key = match.group(0).lower()
        tally[key] = tally.get(key, 0) + 1
    return tally


def summarize(text, bad_words):
    return {
        "original": text,
        "censored": censor_text(text, bad_words),
        "hits": count_hits(text, bad_words),
    }


def format_report(text, bad_words):
    summary = summarize(text, bad_words)
    lines = [
        "original: " + summary["original"],
        "censored: " + summary["censored"],
    ]
    ranked = sorted(
        summary["hits"].items(),
        key=lambda item: (-item[1], item[0]),
    )
    for word, hits in ranked:
        lines.append("  {0}: {1}".format(word, hits))
    if not ranked:
        lines.append("  no matches")
    return "\n".join(lines)


def main(argv):
    if len(argv) < 2:
        print(
            "usage: {0} BAD_WORD [BAD_WORD ...] < input.txt".format(argv[0]),
            file=sys.stderr,
        )
        return 2
    text = sys.stdin.read().rstrip("\n")
    print(format_report(text, argv[1:]))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

