"""Project dictionaries onto a chosen subset of their keys."""

FIELDS = [
    "name",
    "city",
    "email",
]

PEOPLE = [
    {
        "name": "Alice",
        "age": 30,
        "city": "NY",
    },
    {
        "name": "Bob",
        "age": 41,
        "country": "FR",
    },
    {
        "name": "Cleo",
        "city": "LA",
        "age": 27,
    },
]


def filter_dict_by_keys(original_dict, keys_to_keep):
    """Return a new dict holding only the pairs whose key is in keys_to_keep."""
    if not isinstance(original_dict, dict):
        raise TypeError("original_dict must be a dict")
    if isinstance(keys_to_keep, (str, bytes)):
        raise TypeError("keys_to_keep must be a list of strings")
    wanted = set(keys_to_keep)
    return {key: value for key, value in original_dict.items() if key in wanted}


def missing_keys(original_dict, keys_to_keep):
    """List the requested keys that the source dict does not provide."""
    return [key for key in keys_to_keep if key not in original_dict]


def project_records(records, keys_to_keep):
    """Filter every dict of a sequence down to the requested keys."""
    return [filter_dict_by_keys(record, keys_to_keep) for record in records]


def format_record(record, keys_to_keep):
    """Render a filtered record as 'key=value' pairs in the requested order."""
    parts = ["{0}={1}".format(key, record[key]) for key in keys_to_keep if key in record]
    return ", ".join(parts) if parts else "<empty>"


def summarize(records, keys_to_keep):
    """Count the records and the values that survive the projection."""
    filtered = project_records(records, keys_to_keep)
    return {
        "records": len(filtered),
        "values_kept": sum(len(record) for record in filtered),
    }


def build_report(records, keys_to_keep):
    """Build report lines for a batch of records plus coverage information."""
    stats = summarize(records, keys_to_keep)
    lines = [
        "fields: " + ", ".join(keys_to_keep),
        "records: {0}".format(stats["records"]),
        "values kept: {0}".format(stats["values_kept"]),
    ]
    for record in project_records(records, keys_to_keep):
        lines.append(format_record(record, keys_to_keep))
    absent = sorted({key for record in records for key in missing_keys(record, keys_to_keep)})
    if absent:
        lines.append("sometimes missing: " + ", ".join(absent))
    return lines


def main():
    print(filter_dict_by_keys({"a": 1, "b": 2, "c": 3}, ["a", "c"]))
    print(filter_dict_by_keys({"name": "Alice", "age": 30, "city": "NY"}, ["name", "city"]))
    for line in build_report(PEOPLE, FIELDS):
        print(line)


if __name__ == "__main__":
    main()

