def caesar_encrypt(
    text,
    shift,
):
    encrypted_chars = []

    alphabet_ranges = [
        (ord('a'), ord('z'),),
        (ord('A'), ord('Z'),),
    ]

    for char in text:
        original_ord = ord(char)
        is_alpha = False

        for lower_bound, upper_bound, in alphabet_ranges:
            if lower_bound <= original_ord <= upper_bound:
                is_alpha = True
                shifted_ord = (original_ord - lower_bound + shift) % 26 + lower_bound
                encrypted_chars.append(
                    chr(shifted_ord),
                )
                break

        if not is_alpha:
            encrypted_chars.append(
                char,
            )

    return "".join(
        encrypted_chars,
    )

