import re

SEPARATORS = frozenset(
    [
        "-",
        " ",
    ]
)

ACCEPTED_PATTERNS = [
    re.compile(r"^\d{10}$"),
    re.compile(r"^\d{3}[- ]\d{3}[- ]\d{4}$"),
    re.compile(r"^\d{3}[- ]\d{7}$"),
    re.compile(r"^\d{6}[- ]\d{4}$"),
]


def is_valid_us_phone_number(number):
    """Return True when `number` is 10 digits, optionally split by - or spaces."""
    if not isinstance(number, str):
        return False
    candidate = number.strip()
    if not candidate:
        return False
    for char in candidate:
        if not char.isdigit() and char not in SEPARATORS:
            return False
    return any(pattern.match(candidate) for pattern in ACCEPTED_PATTERNS)


def digits_only(number):
    """Strip the accepted separators so only the raw digits remain."""
    return "".join(char for char in number if char.isdigit())


def format_phone_number(number):
    """Normalise a valid number to the canonical 123-456-7890 form."""
    if not is_valid_us_phone_number(number):
        raise ValueError("not a valid US phone number: %r" % (number,))
    raw = digits_only(number)
    return "-".join(
        [
            raw[0:3],
            raw[3:6],
            raw[6:10],
        ]
    )


def classify(numbers):
    """Split an iterable of candidate strings into valid and invalid buckets."""
    report = {
        "valid": [],
        "invalid": [],
    }
    for number in numbers:
        if is_valid_us_phone_number(number):
            report["valid"].append(format_phone_number(number))
        else:
            report["invalid"].append(number)
    return report


def render_report(report):
    lines = [
        "valid numbers: %d" % len(report["valid"]),
        "invalid numbers: %d" % len(report["invalid"]),
    ]
    for canonical in report["valid"]:
        lines.append("  OK      %s" % canonical)
    for rejected in report["invalid"]:
        lines.append("  REJECT  %r" % (rejected,))
    return "\n".join(lines)


def main():
    samples = [
        "123-456-7890",
        "123 456 7890",
        "1234567890",
        "(123) 456-7890",
        "123-45-67890",
        "12-3456-7890",
        "123-456-789",
        "abc-def-ghij",
        "  555 867 5309  ",
    ]
    print(render_report(classify(samples)))


if __name__ == "__main__":
    main()

