SAMPLES = {
    "three": "Line 1\nLine 2\nLine 3",
    "single": "Single line text.",
    "empty": "",
    "trailing": "alpha\nbeta\n",
    "with_blank": "header\n\n   \nfooter",
}


def count_lines_in_text(text):
    """Return the number of lines in a multi-line string."""
    if not isinstance(text, str):
        raise TypeError("count_lines_in_text expects a string")
    return len(text.splitlines())


def line_lengths(text):
    """Return the character length of every line in the text."""
    return [len(line) for line in text.splitlines()]


def text_statistics(text):
    """Summarise a block of text: line count, widths and blank lines."""
    lengths = line_lengths(text)
    blank = sum(1 for line in text.splitlines() if not line.strip())
    return {
        "lines": count_lines_in_text(text),
        "blank_lines": blank,
        "longest_line": max(lengths, default=0),
        "total_characters": sum(lengths),
    }


def format_statistics(name, stats):
    """Render one statistics dictionary as a single readable row."""
    fields = [
        "{:<14}".format(name),
        "lines={:>3}".format(stats["lines"]),
        "blank={:>3}".format(stats["blank_lines"]),
        "widest={:>3}".format(stats["longest_line"]),
        "chars={:>4}".format(stats["total_characters"]),
    ]
    return "  ".join(fields)


def report_header():
    """Return the column header that precedes the statistics rows."""
    columns = [
