def remove_duplicates_unordered(items):
    """Return a new list containing each distinct element of *items* once."""
    seen = set()
    unhashable_seen = []
    unique = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            if item in unhashable_seen:
                continue
            unhashable_seen.append(item)
        unique.append(item)
    return unique


SAMPLES = [
    ("integers", [1, 2, 2, 3, 1, 4]),
    ("letters", ['a', 'b', 'a', 'c']),
    (
        "mixed",
        [1, '1', 1.0, None, None],
    ),
    (
        "nested",
        [[1, 2], [1, 2], [3], (4, 5), (4, 5)],
    ),
    ("empty", []),
]


def duplicate_counts(items):
    """List each repeated value together with its number of extra copies."""
    pairs = []
    for value in remove_duplicates_unordered(items):
        extra = sum(1 for item in items if item == value) - 1
        if extra:
            pairs.append((repr(value), extra))
    return pairs


def summarize(items):
    """Build a small report describing the deduplication of *items*."""
    unique = remove_duplicates_unordered(items)
    return {
        "original_size": len(items),
        "unique_size": len(unique),
        "removed": len(items) - len(unique),
        "unique": unique,
        "duplicates": duplicate_counts(items),
    }


def format_report(label, items):
    """Render the summary of *items* as a list of printable lines."""
    report = summarize(items)
    lines = [
        "{0}: {1}".format(label, items),
        "  unique   -> {0}".format(report["unique"]),
        "  sizes    -> {0} in, {1} out, {2} removed".format(
            report["original_size"],
            report["unique_size"],
            report["removed"],
        ),
    ]
    for text, extra in sorted(report["duplicates"]):
        lines.append("  repeated -> {0} ({1} extra)".format(text, extra))
    return lines


def main():
    for label, items in SAMPLES:
        for line in format_report(label, items):
            print(line)
        print()


if __name__ == "__main__":
