import re
from collections import Counter

HASHTAG_PATTERN = re.compile(r"#([A-Za-z0-9]+)")

REPORT_HEADERS = (
    "hashtag",
    "count",
)

POSTS = [
    "This is a #test with #Python.",
    "No hashtags here!",
    "Learning #python and #Testing, again #test!",
    "Numbers work too: #2024goals and #Py3",
]


def extract_hashtags(text):
    """Return every hashtag in *text*, without the leading '#'."""
    if not isinstance(text, str):
        raise TypeError("extract_hashtags expects a string")
    return HASHTAG_PATTERN.findall(text)


def unique_hashtags(text):
    """Hashtags of a single text, first casing kept, duplicates dropped."""
    seen = set()
    result = []
    for tag in extract_hashtags(text):
        key = tag.lower()
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return result


def count_hashtags(texts):
    """Count hashtags across many texts, grouping case-insensitively."""
    counts = Counter()
    display = {}
    for text in texts:
        for tag in extract_hashtags(text):
            key = tag.lower()
            counts[key] += 1
            display.setdefault(key, tag)
    return {display[key]: count for key, count in counts.most_common()}


def summarize(texts):
    """Collect overall statistics about the hashtags used in *texts*."""
    counts = count_hashtags(texts)
    return {
        "posts": len(texts),
        "unique": len(counts),
        "mentions": sum(counts.values()),
        "top": next(iter(counts), None),
    }


def format_summary(summary):
    """Turn the statistics of :func:`summarize` into printable lines."""
    return [
        "posts analysed:   {}".format(summary["posts"]),
        "unique hashtags:  {}".format(summary["unique"]),
        "hashtag mentions: {}".format(summary["mentions"]),
        "most frequent:    {}".format(summary["top"] or "-"),
    ]


def format_report(counts):
    """Render a hashtag frequency table as lines of text."""
    if not counts:
        return ["(no hashtags found)"]
    head, tail = REPORT_HEADERS
    width = max(len(head), max(len(tag) for tag in counts))
    lines = [
        "{:<{w}}  {}".format(head, tail, w=width),
        "{:<{w}}  {}".format("-" * width, "-" * len(tail), w=width),
    ]
    for tag, count in counts.items():
        lines.append("{:<{w}}  {}".format(tag, count, w=width))
    return lines


def main():
    for post in POSTS:
        print(post)
        print("  ->", unique_hashtags(post))
    print()
    for line in format_report(count_hashtags(POSTS)):
        print(line)
    print()
    for line in format_summary(summarize(POSTS)):
        print(line)


if __name__ == "__main__":
    main()

